"""Generate a Q15 sine lookup table used by the donut renderer."""
import math
from pathlib import Path

N = 1024
values = [round(math.sin(2.0 * math.pi * i / N) * 32767) for i in range(N)]

lines = [
    "/* Generated by tools/gen_sin.py. Q15 sine table, one full turn. */",
    "#ifndef BYTEOS_SIN_TABLE_H",
    "#define BYTEOS_SIN_TABLE_H",
    "",
    "#include <stdint.h>",
    "",
    "static const int16_t sin_table[%d] = {" % N,
]
for start in range(0, N, 8):
    chunk = ", ".join("%6d" % v for v in values[start:start + 8])
    lines.append("    " + chunk + ",")
lines += ["};", "", "#endif", ""]

out = Path(__file__).resolve().parent.parent / "kernel" / "sin_table.h"
out.write_text("\n".join(lines), encoding="ascii")
print("wrote", out)
